// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    address owner = address(0x1234);
    function setUp() public {
        c = new SimpleWallet();
        vm.prank(owner);
        c = new SimpleWallet();
    }
    function testFuzz_property(uint256 depositAmount) public {
        depositAmount = bound(depositAmount, 1, 100 ether);
        vm.assume(depositAmount > 0);
        vm.deal(address(this), depositAmount);
        vm.prank(address(this));
        (bool funded,) = address(c).call{value: depositAmount}("");
        require(funded, "fund failed");
        uint256 ownerBalanceBefore = owner.balance;
        vm.prank(owner);
        c.withdrawAll();
        uint256 ownerBalanceAfter = owner.balance;
        assertTrue(ownerBalanceAfter > ownerBalanceBefore);
    }
}
